//! Metrics for the families this package cannot ship a face for.
//!
//! A deck was laid out against the family it names: its advance widths decide
//! where the lines break, its `hhea` metrics where the first baseline sits.
//! Where that family is one we substitute, the substitute's own metrics move
//! both, so each cluster advances and each line box is measured by the named
//! family's numbers instead — the letterforms stay the substitute's, the words
//! land where PowerPoint put them. Widths are 1/1000 em for `U+0020..=U+007E`
//! plus the marks and accents a European deck reaches for; anything else keeps
//! the substitute's own width.

/// One family's own metrics, all in 1/1000 em.
pub(crate) struct FamilyMetrics {
    /// `hhea` ascender, descender and line gap.
    pub(crate) ascent: i32,
    pub(crate) descent: i32,
    pub(crate) line_gap: i32,
    ascii: [u16; 95],
    extra: &'static [(u16, u16)],
}

struct FamilyEntry {
    family: &'static str,
    bold: bool,
    italic: bool,
    metrics: &'static FamilyMetrics,
}

/// The named family's width for `character`, in em.
pub(crate) fn family_advance(metrics: &FamilyMetrics, character: char) -> Option<f32> {
    let code = character as u32;
    let width = match code
        .checked_sub(0x20)
        .and_then(|index| metrics.ascii.get(index as usize))
    {
        Some(width) => *width,
        None => {
            let code = u16::try_from(code).ok()?;
            let index = metrics
                .extra
                .binary_search_by_key(&code, |(key, _)| *key)
                .ok()?;
            metrics.extra[index].1
        }
    };
    (width > 0).then(|| f32::from(width) / 1000.0)
}

/// The metrics of `family` at this weight and slope, when we have them.
pub(crate) fn family_metrics(
    family: &str,
    bold: bool,
    italic: bool,
) -> Option<&'static FamilyMetrics> {
    FAMILIES
        .iter()
        .find(|entry| entry.family == family && entry.bold == bold && entry.italic == italic)
        .map(|entry| entry.metrics)
}

